style.css:
@-moz-document regexp(".*") {
body {
        background-color: #fffbfa !important;
        margin: 0 !important;
        padding: 20px !important;
        position: relative !important;
    }

    .preview-decor {
        position: absolute !important;
        font-size: 80px !important;
        opacity: 0.08 !important;
    }

    .decor-tl { top: 8% !important; left: 8% !important; }
    .decor-bl { bottom: 10% !important; left: 5% !important; font-size: 90px !important; }
    .decor-tr { top: 12% !important; right: 7% !important; }
    .decor-br { bottom: 8% !important; right: 8% !important; }

    .lace-overlay {
        position: absolute !important;
        top: 0 !important;
        left: 0 !important;
        width: 100% !important;
        height: 100% !important;
        background-color: #fff5f6 !important;
        opacity: 0.6 !important;
    }

    .interface-container {
        background-color: #ffffff !important;
        width: 100% !important;
        max-width: 400px !important;
        margin: 50px auto !important;
        border-radius: 32px !important;
        padding: 30px !important;
        box-shadow: 0 20px 50px rgba(255, 164, 182, 0.1) !important;
        border: 1px solid rgba(255, 255, 255, 0.6) !important;
        position: relative !important;
        z-index: 10 !important;
    }

    .graphic-grid {
        margin-bottom: 24px !important;
        clear: both !important;
        overflow: hidden !important;
    }

    .graphic-card {
        background-color: rgba(255, 255, 255, 0.5) !important;
        border: 1px dashed rgba(255, 164, 182, 0.25) !important;
        border-radius: 20px !important;
        height: 120px !important;
        width: 48% !important;
        float: left !important;
    }

    .graphic-card + .graphic-card {
        float: right !important;
    }

    .simulated-character {
        width: 50px !important;
        height: 50px !important;
        border-radius: 50px !important;
        background: #ffcad4 !important;
        margin: 35px auto !important;
        position: relative !important;
        opacity: 0.7 !important;
    }

    .sparkle-gif-placeholder {
        font-size: 24px !important;
        text-align: center !important;
        line-height: 120px !important;
        opacity: 0.6 !important;
    }

    h1, span, p {
        text-transform: lowercase !important;
    }

    .pink-title {
        color: #ffa4b6 !important;
        font-size: 28px !important;
        font-weight: 500 !important;
        float: left !important;
    }

    .header {
        margin-bottom: 24px !important;
        clear: both !important;
        overflow: hidden !important;
    }

    .all-caps {
        text-transform: uppercase !important;
        font-size: 11px !important;
        font-weight: bold !important;
        letter-spacing: 1px !important;
        color: rgba(99, 83, 83, 0.4) !important;
        float: right !important;
        line-height: 38px !important;
    }

    .task-stack {
        clear: both !important;
    }

    .task-row {
        background-color: rgba(255, 245, 246, 0.4) !important;
        padding: 16px !important;
        border-radius: 16px !important;
        border: 1px solid rgba(255, 164, 182, 0.1) !important;
        margin-bottom: 10px !important;
        clear: both !important;
        overflow: hidden !important;
    }

    .custom-bullet {
        width: 8px !important;
        height: 8px !important;
        background-color: #ffc2b4 !important;
        border-radius: 50px !important;
        float: left !important;
        margin-top: 6px !important;
        margin-right: 14px !important;
    }

    .task-text {
        color: #635353 !important;
        font-size: 15px !important;
        float: left !important;
    }
}
